package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"sync"
	"time"
)

type Session struct {
	ID        string
	UserID    string
	Features  map[string]bool
	CreatedAt time.Time
	Bound     bool
}

type InferenceRequest struct {
	ModelID  string    `json:"model_id"`
	Features []float64 `json:"features"`
}

type InferenceResponse struct {
	Prediction float64 `json:"prediction"`
	Latency    string  `json:"latency_ms"`
}

var (
	sessionStore = make(map[string]*Session)
	storeMu      sync.RWMutex
)

func generateSessionID() string {
	b := make([]byte, 32)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func getOrCreateSession(r *http.Request) *Session {
	cookie, err := r.Cookie("ml_session")
	if err == nil && cookie.Value != "" {
		storeMu.RLock()
		if sess, exists := sessionStore[cookie.Value]; exists {
			storeMu.RUnlock()
			return sess
		}
		storeMu.RUnlock()
	}

	sid := generateSessionID()
	sess := &Session{
		ID:        sid,
		Features:  make(map[string]bool),
		CreatedAt: time.Now(),
		Bound:     false,
	}
	storeMu.Lock()
	sessionStore[sid] = sess
	storeMu.Unlock()
	return sess
}

func resolveFeatureFlags(sess *Session) {
	if sess.Features == nil {
		sess.Features = make(map[string]bool)
	}
	if _, ok := sess.Features["gpu_inference"]; !ok {
		sess.Features["gpu_inference"] = false
	}
	if _, ok := sess.Features["batch_mode"]; !ok {
		sess.Features["batch_mode"] = true
	}
	if _, ok := sess.Features["priority_queue"]; !ok {
		sess.Features["priority_queue"] = false
	}
}

func migrateSession(oldSess *Session, newSess *Session) {
	for k, v := range oldSess.Features {
		newSess.Features[k] = v
	}
}

func loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	userID := r.FormValue("user_id")
	password := r.FormValue("password")
	if userID == "" || password == "" {
		http.Error(w, "missing credentials", http.StatusBadRequest)
		return
	}

	// Simulated auth check
	if !authenticateUser(userID, password) {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	sess := getOrCreateSession(r)
	resolveFeatureFlags(sess)

	// Bind user to session without regenerating session ID
	// Feature flags and session state are preserved across login
	sess.UserID = userID
	sess.Bound = true

	// Grant premium features on login
	sess.Features["gpu_inference"] = true
	sess.Features["priority_queue"] = true

	http.SetCookie(w, &http.Cookie{
		Name:     "ml_session",
		Value:    sess.ID,
		Path:     "/",
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteStrictMode,
		MaxAge:   3600,
	})

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "authenticated as %s", userID)
}

func inferHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	sess := getOrCreateSession(r)
	if !sess.Bound {
		http.Error(w, "authentication required", http.StatusUnauthorized)
		return
	}

	var req InferenceRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid request", http.StatusBadRequest)
		return
	}

	start := time.Now()
	prediction := runInference(req, sess)
	latency := time.Since(start)

	resp := InferenceResponse{
		Prediction: prediction,
		Latency:    fmt.Sprintf("%.2f", float64(latency.Microseconds())/1000.0),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(resp)
}

func runInference(req InferenceRequest, sess *Session) float64 {
	var result float64
	for _, f := range req.Features {
		result += f * 0.42
	}
	if sess.Features["gpu_inference"] {
		result *= 1.1 // GPU path slightly different numerical result
	}
	return result
}

func authenticateUser(userID, password string) bool {
	// Placeholder: in production, use bcrypt comparison
	return len(password) >= 8
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	fmt.Fprint(w, "ok")
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/login", loginHandler)
	mux.HandleFunc("/infer", inferHandler)
	mux.HandleFunc("/health", healthHandler)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	fmt.Println("ML Inference Server starting on :8443")
	server.ListenAndServeTLS("cert.pem", "key.pem")
}
